// constat:template id=go-coverage version=80 sha256=d8c87c49ed045ba3ed8b5f3faeef9c15796c24a4273314386ba01ec3e15af3c0
// Generated by DoneMark's onboarding pull request. Produces the "constat-check-coverage" workflow
// artifact: for every Go test FILE, which lines of which source files it was observed executing.
//
// The third proof. It answers "does this check even run the lines the change added", which is a
// different question from "did it pass" — and it is asked per test file, so one file's answer is
// never another's. `go test` measures coverage natively (-coverprofile, -coverpkg), so nothing
// here instruments anything: it runs the tests of one file at a time, with -run naming exactly
// that file's own test functions, and reads the profile back.
//
// Best-effort by design: a file whose run fails is named in `unmeasured`, with the reason in the
// toolchain's own words, and never takes the rest of the report down with it. "CI tried to measure
// this and failed" and "this file was never in the report" are different facts, and only the first
// is a reason to go and look at CI.
//
// Usage: go run .github/scripts/constat-go-coverage.go <outputFile>
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

// Bounds one CI job's runtime: each entry is one more `go test` process. Above this, coverage
// degrades to "not published for the rest" rather than let one repository's test count run the job
// for an hour. Every file dropped by the cap is named in the job log — never a silent truncation.
const fileCap = 300

var funcLine = regexp.MustCompile(`(?m)^func (Test[A-Za-z0-9_]*)\s*\(`)
var profileLine = regexp.MustCompile(`^(.+):(\d+)\.\d+,(\d+)\.\d+ \d+ (\d+)$`)

type coverageReport struct {
	Schema     string                       `json:"schema"`
	Files      map[string]map[string][]int  `json:"files"`
	Unmeasured map[string]string            `json:"unmeasured"`
}

func theModule(from string) (string, string) {
	dir := from
	for {
		body, err := os.ReadFile(filepath.Join(dir, "go.mod"))
		if err == nil {
			for _, line := range strings.Split(string(body), "\n") {
				if strings.HasPrefix(line, "module ") {
					return strings.TrimSpace(strings.TrimPrefix(line, "module ")), dir
				}
			}
			return "", dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", from
		}
		dir = parent
	}
}

func lastLine(text string) string {
	lines := strings.Split(strings.TrimSpace(text), "\n")
	if len(lines) == 0 {
		return "the run failed and said nothing"
	}
	return strings.TrimSpace(lines[len(lines)-1])
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: constat-go-coverage.go <outputFile>")
		os.Exit(2)
	}
	output := os.Args[1]
	repoRoot, err := os.Getwd()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	modulePath, moduleDir := theModule(repoRoot)

	testFiles := []string{}
	filepath.WalkDir(repoRoot, func(path string, entry fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if entry.IsDir() {
			name := entry.Name()
			if path != repoRoot && (strings.HasPrefix(name, ".") || name == "vendor" || name == "node_modules") {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasSuffix(entry.Name(), "_test.go") {
			relative, err := filepath.Rel(repoRoot, path)
			if err == nil {
				testFiles = append(testFiles, filepath.ToSlash(relative))
			}
		}
		return nil
	})
	sort.Strings(testFiles)
	if len(testFiles) > fileCap {
		fmt.Printf("::warning::%d test files found, coverage capped at %d — %d file(s) will publish no coverage entry this run.\n",
			len(testFiles), fileCap, len(testFiles)-fileCap)
		testFiles = testFiles[:fileCap]
	}

	files := map[string]map[string][]int{}
	unmeasured := map[string]string{}

	for _, testFile := range testFiles {
		body, err := os.ReadFile(filepath.Join(repoRoot, filepath.FromSlash(testFile)))
		if err != nil {
			unmeasured[testFile] = fmt.Sprintf("the file could not be read: %v", err)
			continue
		}
		names := []string{}
		for _, match := range funcLine.FindAllStringSubmatch(string(body), -1) {
			names = append(names, match[1])
		}
		if len(names) == 0 {
			// No test function in it at all — a helper file, not a measurement that failed.
			continue
		}
		profile, err := os.CreateTemp("", "constat-cover-*.out")
		if err != nil {
			unmeasured[testFile] = fmt.Sprintf("no temporary file for the coverage profile: %v", err)
			continue
		}
		profile.Close()
		pkg := "./" + filepath.ToSlash(filepath.Dir(testFile))
		if filepath.Dir(testFile) == "." {
			pkg = "."
		}
		run := exec.Command("go", "test",
			"-run", "^("+strings.Join(names, "|")+")$",
			"-coverprofile", profile.Name(), "-coverpkg", "./...", pkg)
		run.Dir = moduleDir
		said, runErr := run.CombinedOutput()
		if runErr != nil {
			// The run itself failing is a fact about CI, published in CI's own words — never the
			// same silence as a file the report does not mention.
			unmeasured[testFile] = lastLine(string(said))
			os.Remove(profile.Name())
			continue
		}
		perSource := map[string][]int{}
		raw, err := os.ReadFile(profile.Name())
		os.Remove(profile.Name())
		if err != nil {
			unmeasured[testFile] = fmt.Sprintf("the coverage profile could not be read: %v", err)
			continue
		}
		seen := map[string]map[int]bool{}
		for _, line := range strings.Split(string(raw), "\n") {
			match := profileLine.FindStringSubmatch(strings.TrimSpace(line))
			if match == nil {
				continue
			}
			count, _ := strconv.Atoi(match[4])
			if count == 0 {
				continue
			}
			source := match[1]
			switch {
			case modulePath != "" && source == modulePath:
				continue
			case modulePath != "" && strings.HasPrefix(source, modulePath+"/"):
				source = strings.TrimPrefix(source, modulePath+"/")
			default:
				// Compiled from outside this module — a dependency. Never this repository's line.
				continue
			}
			if strings.HasSuffix(source, "_test.go") {
				// A test file crediting itself with "coverage" of its own assertions answers
				// nothing about whether the check touches the change.
				continue
			}
			from, _ := strconv.Atoi(match[2])
			to, _ := strconv.Atoi(match[3])
			if seen[source] == nil {
				seen[source] = map[int]bool{}
			}
			for at := from; at <= to; at++ {
				seen[source][at] = true
			}
		}
		for source, lines := range seen {
			ordered := make([]int, 0, len(lines))
			for at := range lines {
				ordered = append(ordered, at)
			}
			sort.Ints(ordered)
			perSource[source] = ordered
		}
		// Kept even when it is empty: a test file that ran and executed no source line of its own
		// is a real measurement, and dropping it would make it indistinguishable from a file this
		// report never mentions.
		files[testFile] = perSource
	}

	var encoded bytes.Buffer
	writer := json.NewEncoder(&encoded)
	writer.SetEscapeHTML(false)
	writer.SetIndent("", "  ")
	if err := writer.Encode(coverageReport{Schema: "constat.check-coverage/v1", Files: files, Unmeasured: unmeasured}); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := os.MkdirAll(filepath.Dir(output), 0o755); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := os.WriteFile(output, encoded.Bytes(), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Printf("wrote coverage for %d test file(s) to %s (%d unmeasured)\n", len(files), output, len(unmeasured))
}
